// (generated by gen_module_docs.py: the module's docstring ("") and its classes', methods' and functions' (by name))

#pragma once

#include <cstring>

namespace neos::python_runtime::detail::code_docs
{
    struct entry { char const* name; char const* doc; };
    inline entry const sDocs[] =
    {
        { "", "Utilities needed to emulate Python's interactive interpreter.\n\n" },
        { "InteractiveConsole", "Closely emulate the behavior of the interactive Python interpreter.\n\nThis class builds on InteractiveInterpreter and adds prompting\nusing the familiar sys.ps1 and sys.ps2, and input buffering.\n\n" },
        { "InteractiveConsole.__init__", "Constructor.\n\nThe optional locals argument will be passed to the\nInteractiveInterpreter base class.\n\nThe optional filename argument should specify the (file)name\nof the input stream; it will show up in tracebacks.\n\n" },
        { "InteractiveConsole.resetbuffer", "Reset the input buffer." },
        { "InteractiveConsole.interact", "Closely emulate the interactive Python console.\n\nThe optional banner argument specifies the banner to print\nbefore the first interaction; by default it prints a banner\nsimilar to the one printed by the real Python interpreter,\nfollowed by the current class name in parentheses (so as not\nto confuse this with the real interpreter -- since it's so\nclose!).\n\nThe optional exitmsg argument specifies the exit message\nprinted when exiting. Pass the empty string to suppress\nprinting an exit message. If exitmsg is not given or None,\na default message is printed.\n\n" },
        { "InteractiveConsole.push", "Push a line to the interpreter.\n\nThe line should not have a trailing newline; it may have\ninternal newlines.  The line is appended to a buffer and the\ninterpreter's runsource() method is called with the\nconcatenated contents of the buffer as source.  If this\nindicates that the command was executed or invalid, the buffer\nis reset; otherwise, the command is incomplete, and the buffer\nis left as it was after the line was appended.  The return\nvalue is 1 if more input is required, 0 if the line was dealt\nwith in some way (this is the same as runsource()).\n\n" },
        { "InteractiveConsole.raw_input", "Write a prompt and read a line.\n\nThe returned line does not include the trailing newline.\nWhen the user enters the EOF key sequence, EOFError is raised.\n\nThe base implementation uses the built-in function\ninput(); a subclass may replace this with a different\nimplementation.\n\n" },
        { "InteractiveInterpreter", "Base class for InteractiveConsole.\n\nThis class deals with parsing and interpreter state (the user's\nnamespace); it doesn't deal with input buffering or prompting or\ninput file naming (the filename is always passed in explicitly).\n\n" },
        { "InteractiveInterpreter.__init__", "Constructor.\n\nThe optional 'locals' argument specifies a mapping to use as the\nnamespace in which code will be executed; it defaults to a newly\ncreated dictionary with key \"__name__\" set to \"__console__\" and\nkey \"__doc__\" set to None.\n\n" },
        { "InteractiveInterpreter.runsource", "Compile and run some source in the interpreter.\n\nArguments are as for compile_command().\n\nOne of several things can happen:\n\n1) The input is incorrect; compile_command() raised an\nexception (usually SyntaxError).  A syntax traceback will be\nprinted by calling the showsyntaxerror() method.\n\n2) The input is incomplete, and more input is required;\ncompile_command() returned None.  Nothing happens.\n\n3) The input is complete; compile_command() returned a code\nobject.  The code is executed by calling self.runcode() (which\nalso handles run-time exceptions, except for SystemExit).\n\nThe return value is True in case 2, False in the other cases (unless\nan exception is raised).  The return value can be used to\ndecide whether to use sys.ps1 or sys.ps2 to prompt the next\nline.\n\n" },
        { "InteractiveInterpreter.runcode", "Execute a code object.\n\nWhen an exception occurs, self.showtraceback() is called to\ndisplay a traceback.  All exceptions are caught except\nSystemExit, which is reraised.\n\nA note about KeyboardInterrupt: this exception may occur\nelsewhere in this code, and may not always be caught.  The\ncaller should be prepared to deal with it.\n\n" },
        { "InteractiveInterpreter.showsyntaxerror", "Display the syntax error that just occurred.\n\nThis doesn't display a stack trace because there isn't one.\n\nIf a filename is given, it is stuffed in the exception instead\nof what was there before (because Python's parser always uses\n\"<string>\" when reading from a string).\n\nThe output is written by self.write(), below.\n\n" },
        { "InteractiveInterpreter.showtraceback", "Display the exception that just occurred.\n\nWe remove the first stack item because it is our own code.\n\nThe output is written by self.write(), below.\n\n" },
        { "InteractiveInterpreter.write", "Write a string.\n\nThe base implementation writes to sys.stderr; a subclass may\nreplace this with a different implementation.\n\n" },
        { "interact", "Closely emulate the interactive Python interpreter.\n\nThis is a backwards compatible interface to the InteractiveConsole\nclass.  When readfunc is not specified, it attempts to import the\nreadline module to enable GNU readline if it is available.\n\nArguments (all optional, all default to None):\n\nbanner -- passed to InteractiveConsole.interact()\nreadfunc -- if not None, replaces InteractiveConsole.raw_input()\nlocal -- passed to InteractiveInterpreter.__init__()\nexitmsg -- passed to InteractiveConsole.interact()\nlocal_exit -- passed to InteractiveConsole.__init__()\n\n" },
    };
    inline char const* doc(char const* aName)
    {
        for (auto const& e : sDocs)
            if (std::strcmp(e.name, aName) == 0)
                return e.doc;
        return nullptr;
    }
}
